"""Private helpers shared by the workspace components.

Only the Python standard library is used.  This module is intentionally
small so that each component can import it by inserting the workspace root
on ``sys.path`` (which makes the same helpers available regardless of the
current working directory).
"""

import json
import math
from pathlib import Path


def load_json(path):
    """Read a UTF-8 JSON document.  Top level must be an object or array."""
    p = Path(path)
    try:
        text = p.read_text(encoding="utf-8")
    except UnicodeDecodeError as exc:
        raise ValueError("payload is not valid UTF-8: %s" % path) from exc
    except OSError as exc:
        raise ValueError("cannot read payload: %s" % path) from exc
    try:
        data = json.loads(text)
    except json.JSONDecodeError as exc:
        raise ValueError("payload is not valid JSON: %s" % path) from exc
    if not isinstance(data, (dict, list)):
        raise ValueError("payload top level must be an object or array")
    return data


def write_json(path, data):
    """Write a product JSON file using the required canonical formatting."""
    p = Path(path)
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(
        json.dumps(data, ensure_ascii=False, sort_keys=True, indent=2, allow_nan=False) + "\n",
        encoding="utf-8",
    )


def compact_bytes(data):
    """Canonical compact serialization used by the final report hash."""
    return json.dumps(
        data,
        ensure_ascii=False,
        sort_keys=True,
        separators=(",", ":"),
        allow_nan=False,
    ).encode("utf-8")


def ensure_finite(obj):
    """Raise ValueError if any nested numeric JSON value is NaN/Infinity."""
    if isinstance(obj, float):
        if math.isnan(obj) or math.isinf(obj):
            raise ValueError("non-finite number is not allowed")
    elif isinstance(obj, dict):
        for key, value in obj.items():
            ensure_finite(key)
            ensure_finite(value)
    elif isinstance(obj, list):
        for value in obj:
            ensure_finite(value)
    # int, bool, str and None are always finite for our purposes.


def unwrap(payload):
    """Return result from an upstream envelope, otherwise the payload itself."""
    if isinstance(payload, dict) and set(payload) == {"name", "result"}:
        return payload["result"]
    return payload


def expect_dict(value, what):
    if not isinstance(value, dict):
        raise ValueError("%s must be an object" % what)
    return value


def expect_list(value, what):
    if not isinstance(value, list):
        raise ValueError("%s must be a list" % what)
    return value


def expect_str(value, what, nonempty=True):
    if not isinstance(value, str):
        raise ValueError("%s must be a string" % what)
    if nonempty and value.strip() == "":
        raise ValueError("%s must be a non-empty string" % what)
    return value


def expect_int(value, what):
    if isinstance(value, bool) or not isinstance(value, int):
        raise ValueError("%s must be an integer" % what)
    return value

