import heapq
import sys
from pathlib import Path

_ROOT = Path(__file__).resolve().parents[2]
if str(_ROOT) not in sys.path:
    sys.path.insert(0, str(_ROOT))

from _common import (  # noqa: E402
    ensure_finite,
    expect_dict,
    expect_int,
    expect_list,
    expect_str,
    unwrap,
)


def _read_ids(value, key, node_set, what):
    raw = expect_list(value, what)
    ids = []
    for item in raw:
        ident = expect_str(item, what + " id")
        if ident not in node_set:
            raise ValueError("%s references unknown node: %s" % (what, ident))
        ids.append(ident)
    return ids


def transform(payloads, contract):
    if not isinstance(payloads, list):
        raise ValueError("payloads must be a list")
    inputs = contract.get("inputs", [])
    if len(payloads) != len(inputs):
        raise ValueError("payloads length does not match contract inputs")
    for payload in payloads:
        ensure_finite(payload)

    data = expect_dict(unwrap(payloads[0]), "route_graph input")

    nodes_raw = expect_list(data.get("nodes"), "nodes")
    node_set = set()
    for node in nodes_raw:
        ident = expect_str(node, "node id")
        if ident in node_set:
            raise ValueError("duplicate node id: %s" % ident)
        node_set.add(ident)

    edges_raw = expect_list(data.get("edges"), "edges")
    edge_set = set()
    edge_weight = {}
    for edge in edges_raw:
        edge = expect_dict(edge, "edge")
        src = expect_str(edge.get("from"), "edge.from")
        dst = expect_str(edge.get("to"), "edge.to")
        weight = expect_int(edge.get("weight"), "edge.weight")
        if weight < 1:
            raise ValueError("edge.weight must be >= 1")
        if src not in node_set or dst not in node_set:
            raise ValueError("edge endpoint is not in nodes")
        key = (src, dst)
        if key in edge_set:
            raise ValueError("duplicate directed edge: %s->%s" % (src, dst))
        edge_set.add(key)
        edge_weight[key] = weight

    sources = _read_ids(data.get("sources"), "sources", node_set, "source")
    targets = _read_ids(data.get("targets"), "targets", node_set, "target")

    failed_nodes_raw = _read_ids(
        data.get("failed_nodes"), "failed_nodes", node_set, "failed node"
    )
    failed_node_set = set(failed_nodes_raw)

    failed_edges_raw = expect_list(data.get("failed_edges"), "failed_edges")
    failed_edge_set = set()
    for entry in failed_edges_raw:
        entry = expect_list(entry, "failed_edge")
        if len(entry) != 2:
            raise ValueError("failed_edge must be [from, to]")
        src = expect_str(entry[0], "failed_edge.from")
        dst = expect_str(entry[1], "failed_edge.to")
        key = (src, dst)
        if key not in edge_set:
            raise ValueError("failed_edge does not exist: %s->%s" % (src, dst))
        failed_edge_set.add(key)

    active_edges = []
    adjacency = {}
    for key in sorted(edge_set):
        src, dst = key
        if src in failed_node_set or dst in failed_node_set:
            continue
        if key in failed_edge_set:
            continue
        weight = edge_weight[key]
        active_edges.append({"from": src, "to": dst, "weight": weight})
        adjacency.setdefault(src, []).append((dst, weight))

    distance_cache = {}

    def dijkstra(start):
        if start in distance_cache:
            return distance_cache[start]
        dist = {start: 0}
        heap = [(0, start)]
        while heap:
            current, node = heapq.heappop(heap)
            if current != dist[node]:
                continue
            for nxt, weight in adjacency.get(node, []):
                candidate = current + weight
                if candidate < dist.get(nxt, float("inf")):
                    dist[nxt] = candidate
                    heapq.heappush(heap, (candidate, nxt))
        distance_cache[start] = dist
        return dist

    routes = []
    for source in sorted(set(sources)):
        if source in failed_node_set:
            source_dist = None
        else:
            source_dist = dijkstra(source)
        for target in sorted(set(targets)):
            if source in failed_node_set or target in failed_node_set:
                routes.append(
                    {"source": source, "target": target, "distance": None, "next_hops": []}
                )
            elif source == target:
                routes.append(
                    {"source": source, "target": target, "distance": 0, "next_hops": []}
                )
            else:
                distance = source_dist.get(target)
                if distance is None:
                    routes.append(
                        {
                            "source": source,
                            "target": target,
                            "distance": None,
                            "next_hops": [],
                        }
                    )
                else:
                    next_hops = []
                    for nxt, weight in adjacency.get(source, []):
                        target_dist = dijkstra(nxt).get(target)
                        if target_dist is not None and distance == weight + target_dist:
                            next_hops.append(nxt)
                    routes.append(
                        {
                            "source": source,
                            "target": target,
                            "distance": distance,
                            "next_hops": sorted(set(next_hops)),
                        }
                    )

    return {
        "name": contract["name"],
        "result": {"routes": routes, "active_edges": active_edges},
    }

