import fnmatch
import sys
from pathlib import Path

_ROOT = Path(__file__).resolve().parents[2]
if str(_ROOT) not in sys.path:
    sys.path.insert(0, str(_ROOT))

from _common import (  # noqa: E402
    ensure_finite,
    expect_dict,
    expect_int,
    expect_list,
    expect_str,
    unwrap,
)

PROTOCOLS_RULE = ("tcp", "udp", "*")
PROTOCOLS_EVENT = ("tcp", "udp")
FLAGS = ("syn", "data", "fin", "rst")
EFFECTS = ("allow", "deny")


def _specificity(rule):
    total = 0
    for text in (rule["src"], rule["dst"], rule["protocol"]):
        for char in text:
            if char not in "*?[]":
                total += 1
    return total


def _glob_match(pattern, text):
    return fnmatch.fnmatchcase(text, pattern)


def _protocol_matches(pattern, protocol):
    return pattern == "*" or pattern == protocol


def _session_key(event):
    endpoint_a = (event["src"], event["sport"])
    endpoint_b = (event["dst"], event["dport"])
    left, right = sorted((endpoint_a, endpoint_b))
    return (event["protocol"], left[0], left[1], right[0], right[1])


def transform(payloads, contract):
    if not isinstance(payloads, list):
        raise ValueError("payloads must be a list")
    inputs = contract.get("inputs", [])
    if len(payloads) != len(inputs):
        raise ValueError("payloads length does not match contract inputs")
    for payload in payloads:
        ensure_finite(payload)

    data = expect_dict(unwrap(payloads[0]), "firewall_policy input")

    timeout = expect_int(data.get("timeout"), "timeout")
    if timeout < 1:
        raise ValueError("timeout must be >= 1")

    rules = []
    rule_ids = set()
    for raw in expect_list(data.get("rules"), "rules"):
        raw = expect_dict(raw, "rule")
        rule_id = expect_str(raw.get("id"), "rule.id")
        if rule_id in rule_ids:
            raise ValueError("duplicate rule id: %s" % rule_id)
        rule_ids.add(rule_id)
        src = expect_str(raw.get("src"), "rule.src")
        dst = expect_str(raw.get("dst"), "rule.dst")
        protocol = expect_str(raw.get("protocol"), "rule.protocol")
        if protocol not in PROTOCOLS_RULE:
            raise ValueError("invalid rule.protocol: %s" % protocol)
        priority = expect_int(raw.get("priority"), "rule.priority")
        effect = expect_str(raw.get("effect"), "rule.effect")
        if effect not in EFFECTS:
            raise ValueError("invalid rule.effect: %s" % effect)
        rules.append(
            {
                "id": rule_id,
                "src": src,
                "dst": dst,
                "protocol": protocol,
                "priority": priority,
                "effect": effect,
            }
        )

    rules.sort(
        key=lambda rule: (
            -rule["priority"],
            -_specificity(rule),
            0 if rule["effect"] == "deny" else 1,
            rule["id"],
        )
    )

    events = []
    event_ids = set()
    for raw in expect_list(data.get("events"), "events"):
        raw = expect_dict(raw, "event")
        event_id = expect_str(raw.get("id"), "event.id")
        if event_id in event_ids:
            raise ValueError("duplicate event id: %s" % event_id)
        event_ids.add(event_id)
        ts = expect_int(raw.get("ts"), "event.ts")
        if ts < 0:
            raise ValueError("event.ts must be >= 0")
        seq = expect_int(raw.get("seq"), "event.seq")
        if seq < 0:
            raise ValueError("event.seq must be >= 0")
        src = expect_str(raw.get("src"), "event.src")
        dst = expect_str(raw.get("dst"), "event.dst")
        sport = expect_int(raw.get("sport"), "event.sport")
        if not 1 <= sport <= 65535:
            raise ValueError("event.sport must be in 1..65535")
        dport = expect_int(raw.get("dport"), "event.dport")
        if not 1 <= dport <= 65535:
            raise ValueError("event.dport must be in 1..65535")
        protocol = expect_str(raw.get("protocol"), "event.protocol")
        if protocol not in PROTOCOLS_EVENT:
            raise ValueError("invalid event.protocol: %s" % protocol)
        flag = expect_str(raw.get("flag"), "event.flag")
        if flag not in FLAGS:
            raise ValueError("invalid event.flag: %s" % flag)
        events.append(
            {
                "id": event_id,
                "ts": ts,
                "seq": seq,
                "src": src,
                "dst": dst,
                "sport": sport,
                "dport": dport,
                "protocol": protocol,
                "flag": flag,
            }
        )

    events.sort(key=lambda event: (event["ts"], event["seq"], event["id"]))

    sessions = {}
    decisions = []

    for event in events:
        expired = [
            key
            for key, last_activity in sessions.items()
            if event["ts"] >= last_activity + timeout
        ]
        for key in expired:
            del sessions[key]

        key = _session_key(event)

        if key in sessions:
            sessions[key] = event["ts"]
            decisions.append(
                {
                    "id": event["id"],
                    "allowed": True,
                    "reason": "state",
                    "rule_id": None,
                    "src": event["src"],
                    "dst": event["dst"],
                }
            )
            if event["flag"] in ("fin", "rst"):
                del sessions[key]
            continue

        if event["flag"] != "syn":
            decisions.append(
                {
                    "id": event["id"],
                    "allowed": False,
                    "reason": "no_session",
                    "rule_id": None,
                    "src": event["src"],
                    "dst": event["dst"],
                }
            )
            continue

        winner = None
        for rule in rules:
            if (
                _protocol_matches(rule["protocol"], event["protocol"])
                and _glob_match(rule["src"], event["src"])
                and _glob_match(rule["dst"], event["dst"])
            ):
                winner = rule
                break

        if winner is None:
            decisions.append(
                {
                    "id": event["id"],
                    "allowed": False,
                    "reason": "default",
                    "rule_id": None,
                    "src": event["src"],
                    "dst": event["dst"],
                }
            )
        elif winner["effect"] == "allow":
            sessions[key] = event["ts"]
            decisions.append(
                {
                    "id": event["id"],
                    "allowed": True,
                    "reason": "rule",
                    "rule_id": winner["id"],
                    "src": event["src"],
                    "dst": event["dst"],
                }
            )
        else:
            decisions.append(
                {
                    "id": event["id"],
                    "allowed": False,
                    "reason": "rule",
                    "rule_id": winner["id"],
                    "src": event["src"],
                    "dst": event["dst"],
                }
            )

    return {
        "name": contract["name"],
        "result": {
            "decisions": decisions,
            "active_sessions": len(sessions),
        },
    }

