            raise ValueError("decision.allowed must be a boolean")
        src = expect_str(raw.get("src"), "decision.src")
        dst = expect_str(raw.get("dst"), "decision.dst")
        if decision_id in decisions:
            raise ValueError("duplicate decision id: %s" % decision_id)
        decisions[decision_id] = {"allowed": allowed, "src": src, "dst": dst}

    routes = {}
    for raw in expect_list(routes_data.get("routes"), "routes"):
        raw = expect_dict(raw, "route")
        source = expect_str(raw.get("source"), "route.source")
        target = expect_str(raw.get("target"), "route.target")
        distance = raw.get("distance")
