        next_hops = []
        for hop in expect_list(raw.get("next_hops"), "route.next_hops"):
            next_hops.append(expect_str(hop, "route.next_hop"))
        key = (source, target)
        value = (distance, tuple(next_hops))
        if key in routes and routes[key] != value:
            raise ValueError("conflicting duplicate route for %s->%s" % key)
