                            reason = "non_shortest"
                    else:
                        if total != distance or hops[1] not in next_hops:
                            reason = "non_shortest"

        reachable = reason is None
        if reachable:
            reason = "ok"
        results.append(
            {"id": probe["id"], "reachable": reachable, "reason": reason}
        )

    reachable_count = sum(1 for result in results if result["reachable"])

    return {
        "name": contract["name"],
        "result": {"results": results, "reachable_count": reachable_count},
    }

