import json
import subprocess
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent


def discover_contracts():
    contracts = []
    for path in ROOT.rglob("contract.json"):
        if "outputs" in path.relative_to(ROOT).parts:
            continue
        contracts.append(path)
    return sorted(contracts)


def build_order(contract_paths):
    name_to_path = {}
    output_to_name = {}
    parsed = {}
    for path in contract_paths:
        contract = json.loads(path.read_text(encoding="utf-8"))
        name = contract["name"]
        name_to_path[name] = path
        parsed[name] = contract
        output_to_name[contract["output"]] = name

    dependencies = {}
    for name, contract in parsed.items():
        deps = set()
        for input_path in contract["inputs"]:
            if input_path in output_to_name and output_to_name[input_path] != name:
                deps.add(output_to_name[input_path])
        dependencies[name] = deps

    order = []
    remaining = {name: set(deps) for name, deps in dependencies.items()}
    while remaining:
        ready = sorted(name for name, deps in remaining.items() if not deps)
        if not ready:
            raise ValueError("component dependency cycle detected")
        for name in ready:
            del remaining[name]
            order.append(name)
        for name in list(remaining):
            remaining[name] -= set(ready)
    return order, name_to_path


def run_all():
    contract_paths = discover_contracts()
    order, name_to_path = build_order(contract_paths)

    for name in order:
        render_path = name_to_path[name].with_name("render.py")
        subprocess.run(
            [sys.executable, str(render_path)], cwd=ROOT, check=True, timeout=60
        )

    subprocess.run([sys.executable, str(ROOT / "integrate.py")], cwd=ROOT, check=True, timeout=60)
    subprocess.run([sys.executable, str(ROOT / "final_report.py")], cwd=ROOT, check=True, timeout=60)


if __name__ == "__main__":
    run_all()

