from _common import write_json  # noqa: E402


def _needs_attention(result):
    if not isinstance(result, dict):
        return False
    if result.get("blocked") is True:
        return True
    if result.get("feasible") is False:
        return True
    if result.get("compatible") is False:
        return True
    deny = result.get("deny")
    if isinstance(deny, (int, float)) and not isinstance(deny, bool) and deny > 0:
        return True
    score_total = result.get("score_total")
    if (
        isinstance(score_total, (int, float))
        and not isinstance(score_total, bool)
        and score_total >= 20
    ):
        return True
    return False


def main():
    manifest_path = ROOT / "outputs" / "core_manifest.json"
    core_object = json.loads(manifest_path.read_text(encoding="utf-8"))
