        raise ValueError("core_manifest.json must contain a components object")

    components = core_object["components"]
    if not isinstance(components, dict):
        raise ValueError("components must be an object")

    serialized = json.dumps(
        core_object,
        ensure_ascii=False,
        sort_keys=True,
        separators=(",", ":"),
        allow_nan=False,
    ).encode("utf-8")
    sha256 = hashlib.sha256(serialized).hexdigest()

    attention = sorted(
        name for name, result in components.items() if _needs_attention(result)
    )

    report = {
        "title": "网络策略收敛",
        "component_count": len(components),
        "sha256": sha256,
        "attention": attention,
    }
